      "pt": "Experiência em formação técnica e conhecimentos de AWS. Lecionar o currículo oficial AWS re/Start e preparar para a certificação AWS Certified Cloud Practitioner. Enviar CV, certificações AWS, experiência como formador/a e proposta de honorários (também para ngomeze@sic4change.org) com o assunto «Ref. 09/26 – Personal docente Novabit AWS» (escrever tal como está). Prazo: até 1 de outubro."
