      "pt": "Para intervenção com famílias, jovens e pessoas com problemas de integração social e vulnerabilidade. Valoriza-se experiência em inserção profissional e empregabilidade, e em projetos com pessoas com deficiência e jovens que estiveram sob tutela. Carta de condução e carro próprio obrigatórios. Entrada imediata. Enviar CV antes de 04/10/2026 através de https://asociaciónsumas.com/ofertas-de-empleo/ (não se aceita outro meio de envio)."
